pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address expectedOwner) public {
        // The deployer of C is address(this) in setUp, which is the test contract itself.
        // The reference contract should return this deployment address as the owner.
        // The mutated version returns address(0), so it will differ for any input.
        // We fuzz 'expectedOwner' to show the property holds: owner() must equal the deployer, not the fuzzed value.
