pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(attacker != newOwner);
        vm.assume(attacker != address(c));

        // Attacker deploys a small contract that calls c.transferOwnership on its behalf
        vm.prank(attacker);
        ProxyCaller proxy = new ProxyCaller();
        vm.deal(address(proxy), 0);

        // Record owner before
        address originalOwner = c.owner();

        // The proxy attempts to transfer ownership to newOwner by calling c.transferOwnership
        vm.prank(attacker);
        (bool ok, ) = address(proxy).call(abi.encodeWithSelector(ProxyCaller.forward.selector, address(c), newOwner));
        // If ok is true, the call did not revert in the top-level; the reference contract should have caused an external revert anyway because the proxy is not the owner.
        // The assertion: if ok is true, ownership must remain unchanged; the buggy version may have allowed the owner to change.
        assertTrue(!ok || c.owner() == originalOwner);
    }
}

contract ProxyCaller {
    function forward(address target, address newOwner) external {
        (bool success, ) = target.call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        require(success);
    }
}

