pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // Transfer ownership to the fuzzed newOwner (could be zero or non-zero)
        vm.prank(c.owner());
        bool firstOk = true;
        try c.transferOwnership(newOwner) {} catch { firstOk = false; }
        if (!firstOk) return; // if first call reverts, we don't continue

        // If current owner is zero (renounced), a second call to transferOwnership(address(0)) must revert
        if (c.owner() == address(0)) {
            vm.prank(address(0)); // prank from zero to simulate a call after renounce (any caller works, zero is fine)
            bool secondOk = true;
            try c.transferOwnership(address(0)) {} catch { secondOk = false; }
            assertTrue(!secondOk);
        }
    }
}

