pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // 1. Renounce ownership first to set owner to address(0)
        c.renounceOwnership();
        require(c.owner() == address(0), "setup: owner not zero after renounce");

        // 2. fuzzed input is the newOwner argument to transferOwnership
        // The decisive case is newOwner == address(0); but we let the fuzzer explore.
        // We must ensure that the reference's onlyOwner check passes;
        // after renounce, onlyOwner would revert because msg.sender != owner.
        // To pass the modifier, we must prank as the owner... but owner is zero.
        // Actually, we want to test the zero-address check INSIDE the function body,
        // which is reached only after onlyOwner passes. But with owner=0 and msg.sender=0,
        // the modifier passes because _msgSender()==0 and owner()==0.
        // So we prank as address(0) to satisfy onlyOwner.
        vm.prank(address(0));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. General rule: If the previous owner is address(0) (ownership renounced),
        // calling transferOwnership (even with newOwner=0) must always revert because
        // the function requires newOwner != address(0). The bug removes this require, so
        // it succeeds when newOwner == address(0). So the property: call must fail for all newOwner.
        assertTrue(!ok, "transferOwnership should revert after renounceOwnership");
    }
}

